// @ts-check
/** @typedef {import('../../InvocationContext.js').InvocationContext} InvocationContext */

import { Command } from '../../../utils/Command.js'
import { CommandType } from '../../../utils/CommandType.js'
import { RuntimeName } from '../../../utils/RuntimeName.js'
import { getCurrentCommandPayload } from './TypeParsingUtils.js'
import { Color, Duration, Point, Uuid, colorChannel } from '../../../utils/DrawingTypes.js'

/**
 * @param {InvocationContext} invocationContext
 * @returns {Date}
 */
export function parseInstant(invocationContext) {
    const iso = String(getCurrentCommandPayload(invocationContext)[1])
    return new Date(iso)
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {Date}
 */
export function parseOffsetDateTime(invocationContext) {
    const iso = String(getCurrentCommandPayload(invocationContext)[1])
    return new Date(iso)
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {string}
 */
export function parseUUID(invocationContext) {
    return String(getCurrentCommandPayload(invocationContext)[1])
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {Date}
 */
export function parseLocalTime(invocationContext) {
    const iso = String(getCurrentCommandPayload(invocationContext)[1])
    // Parse time-only ISO string (e.g. "HH:MM:SS.nnnnnnnnn") on epoch day
    return new Date(`1970-01-01T${iso}Z`)
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {number} total milliseconds
 */
export function parseDuration(invocationContext) {
    const payload = getCurrentCommandPayload(invocationContext)
    const seconds = Number(payload[1])
    const nanoAdjustment = Number(payload[2])
    return seconds * 1000 + nanoAdjustment / 1_000_000
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {URL}
 */
export function parseURI(invocationContext) {
    return new URL(String(getCurrentCommandPayload(invocationContext)[1]))
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {Point}
 */
export function parsePoint(invocationContext) {
    const payload = getCurrentCommandPayload(invocationContext)
    return new Point(Number(payload[1]), Number(payload[2]))
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {Color}
 */
export function parseColor(invocationContext) {
    const payload = getCurrentCommandPayload(invocationContext)
    const a = Number(payload[1])
    const r = Number(payload[2])
    const g = Number(payload[3])
    const b = Number(payload[4])
    return new Color(r, g, b, a)
}

/** Inbound: JVM result type string → JavaScript object */
export const JavaTypeParsingFunctions = new Map(
    /** @type {[string, (invocationContext: InvocationContext) => unknown][]} */ ([
        ['java.time.Instant', parseInstant],
        ['java.time.OffsetDateTime', parseOffsetDateTime],
        ['java.util.UUID', parseUUID],
        ['java.awt.Point', parsePoint],
        ['java.awt.Color', parseColor],
        ['java.time.LocalTime', parseLocalTime],
        ['java.time.Duration', parseDuration],
        ['java.net.URI', parseURI],
    ])
)

/** Outbound: JavaScript object → Command graph targeting the JVM runtime */
export const JavaParsingArgument = new Map(
    /** @type {[Function, (value: any) => Command][]} */ ([
        [
            Date,
            (/** @type {Date} */ value) =>
                new Command(RuntimeName.Jvm, CommandType.InvokeStaticMethod, [
                    new Command(RuntimeName.Jvm, CommandType.GetType, ['java.time.Instant']),
                    'parse',
                    value.toISOString(),
                ]),
        ],
        [
            URL,
            (/** @type {URL} */ value) =>
                new Command(RuntimeName.Jvm, CommandType.InvokeStaticMethod, [
                    new Command(RuntimeName.Jvm, CommandType.GetType, ['java.net.URI']),
                    'create',
                    value.href,
                ]),
        ],
        [
            Point,
            (/** @type {Point} */ value) =>
                new Command(RuntimeName.Jvm, CommandType.CreateClassInstance, [
                    new Command(RuntimeName.Jvm, CommandType.GetType, ['java.awt.Point']),
                    value.x,
                    value.y,
                ]),
        ],
        [
            Color,
            (/** @type {Color} */ value) =>
                new Command(RuntimeName.Jvm, CommandType.CreateClassInstance, [
                    new Command(RuntimeName.Jvm, CommandType.GetType, ['java.awt.Color']),
                    colorChannel(value.r),
                    colorChannel(value.g),
                    colorChannel(value.b),
                    colorChannel(value.a),
                ]),
        ],
        [
            Duration,
            (/** @type {Duration} */ value) => {
                const ms = value.milliseconds
                const seconds = Math.trunc(ms / 1000)
                const nanos = (ms % 1000) * 1_000_000
                return new Command(RuntimeName.Jvm, CommandType.InvokeStaticMethod, [
                    new Command(RuntimeName.Jvm, CommandType.GetType, ['java.time.Duration']),
                    'ofSeconds',
                    seconds,
                    nanos,
                ])
            },
        ],
        [
            Uuid,
            (/** @type {Uuid} */ value) =>
                new Command(RuntimeName.Jvm, CommandType.InvokeStaticMethod, [
                    new Command(RuntimeName.Jvm, CommandType.GetType, ['java.util.UUID']),
                    'fromString',
                    value.value,
                ]),
        ],
    ])
)
